function minOperations(n) {
  // Build the array; each operation removes at most one unit of surplus above the average.
  const arr = Array.from({ length: n }, (_, i) => 2 * i + 1);
  const average = arr.reduce((a, b) => a + b, 0) / n;
  let surplus = 0;
  for (const value of arr) if (value > average) surplus += value - average;
  return surplus;
}

